import json
import pandas as pd

FIELD_MAP = {
    "user_id": "user_id", "id": "user_id", "userId": "user_id",
    "email": "email", "email_address": "email",
    "full_name": "name", "name": "name", "userName": "name",
    "registration_date": "created_date", "created_at": "created_date", "joined": "created_date",
    "status": "status", "is_active": "status", "active": "status",
}

UNIFIED_FIELDS = ["user_id", "name", "email", "created_date", "status"]


def normalize_status(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, str):
        return value
    return str(value)


def normalize_date(value):
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return None
    s = str(value)
    return pd.to_datetime(s).strftime("%Y-%m-%d")


def normalize_record(raw):
    unified = {}
    for key, value in raw.items():
        if key not in FIELD_MAP:
            continue
        unified_key = FIELD_MAP[key]
        if unified_key == "status":
            value = normalize_status(value)
        elif unified_key == "created_date":
            value = normalize_date(value)
        elif unified_key == "user_id":
            value = int(value)
        elif isinstance(value, str):
            value = value
        unified[unified_key] = value
    return unified


def load_source_a():
    with open("/data/source_a/users.json") as f:
        rows = json.load(f)
    return [normalize_record(r) for r in rows]


def load_source_b():
    df = pd.read_csv("/data/source_b/users.csv")
    return [normalize_record(r) for r in df.to_dict(orient="records")]


def load_source_c():
    df = pd.read_parquet("/data/source_c/users.parquet")
    return [normalize_record(r) for r in df.to_dict(orient="records")]


def main():
    sources = {
        "source_a": load_source_a(),
        "source_b": load_source_b(),
        "source_c": load_source_c(),
    }

    by_user = {}
    for source_name, records in sources.items():
        for rec in records:
            uid = rec["user_id"]
            by_user.setdefault(uid, {})[source_name] = rec

    priority = ["source_a", "source_b", "source_c"]
    merged_rows = []
    conflicts = []

    for uid in sorted(by_user):
        per_source = by_user[uid]
        merged = {"user_id": uid}
        for field in ["name", "email", "created_date", "status"]:
            values_by_source = {}
            for src in priority:
                if src in per_source and per_source[src].get(field) is not None:
                    values_by_source[src] = per_source[src][field]
            if not values_by_source:
                merged[field] = None
                continue
            selected = next(values_by_source[s] for s in priority if s in values_by_source)
            merged[field] = selected
            distinct = set(values_by_source.values())
            if len(distinct) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": {s: values_by_source[s] for s in priority if s in values_by_source},
                    "selected": selected,
                })
        merged_rows.append(merged)

    out_df = pd.DataFrame(merged_rows, columns=UNIFIED_FIELDS)
    out_df["user_id"] = out_df["user_id"].astype("int64")
    out_df["name"] = out_df["name"].astype("string")
    out_df["email"] = out_df["email"].astype("string")
    out_df["created_date"] = out_df["created_date"].astype("string")
    out_df["status"] = out_df["status"].astype("string")
    out_df.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)

    print(out_df)
    print(f"\nTotal conflicts: {len(conflicts)}")
    for c in conflicts:
        print(c)


if __name__ == "__main__":
    main()

